{
  "lesson_summary": "Today's lesson plans to teach children to count numbers from 0 to 9, and to write and read these numbers both as numerals and in words. The lesson uses examples like counting raised fingers and butterflies, then writing the corresponding numeral and word.",
  "lesson_summary_short": "Today's lesson plans to teach counting numbers from 0 to 9, using two raised fingers as an example.",
  "checks_summary": "This quiz checks whether the class can count objects, and read and write numbers up to 9 in both numerals and words.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which of these is the numeral for 'two'?",
      "options": [
        "2",
        "3",
        "4"
      ],
      "correct_index": 0,
      "explanation": "The numeral '2' represents the quantity of two.",
      "selected_because": "The lesson used 'two' as its first example.",
      "distractor_misconceptions": {
        "1": "confuses 'two' with 'three'",
        "2": "confuses 'two' with 'four'"
      },
      "option_feedback": {
        "correct": "That's right! The numeral '2' shows the count of two, just like the two fingers you counted in class.",
        "wrong": {
          "1": "This is the numeral for 'three'. Remember, 'two' is the number after 'one' and before 'three'.",
          "2": "This is the numeral for 'four'. The lesson showed how two fingers match the numeral '2'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "The last count word is two — write 2",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "How many butterflies are there?",
      "options": [
        "5",
        "6",
        "4"
      ],
      "correct_index": 1,
      "explanation": "Counting each butterfly one by one shows there are 6 butterflies.",
      "selected_because": "The lesson used a picture of butterflies to count.",
      "distractor_misconceptions": {
        "0": "miscounts the total number of butterflies",
        "2": "counts one less than the actual number"
      },
      "option_feedback": {
        "correct": "Great job! There are 6 butterflies. Remember to touch each one as you count to be sure.",
        "wrong": {
          "0": "Let's count them again. Touch each butterfly as you say the number. You will find there are 6 butterflies.",
          "2": "Almost! If you count carefully, touching each butterfly, you will see there are 6 in total."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "butterfly",
        "count": 6
      },
      "figure_role": "read_off",
      "source_quote": "Count the butterflies and write the numeral in the box.",
      "teaching_error": null
    },
    {
      "slo_id": "S3",
      "level": "understand",
      "question": "Which word is for the numeral 6?",
      "options": [
        "six",
        "five",
        "four"
      ],
      "correct_index": 0,
      "explanation": "The word 'six' represents the numeral 6.",
      "selected_because": "The lesson specifically asked to write the number 6 in words.",
      "distractor_misconceptions": {
        "1": "confuses 'six' with 'five' due to similar sounds",
        "2": "confuses 'six' with 'four'"
      },
      "option_feedback": {
        "correct": "You got it! The word 'six' is how we write the numeral 6. Always read the numeral aloud to check.",
        "wrong": {
          "1": "This is the word 'five'. Remember, the lesson said to read the numeral aloud to check if the word matches. '6' sounds like 'six'.",
          "2": "This is the word 'four'. The lesson showed that the numeral 6 is written as 'six'."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number 6 in words.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How do you write 'four' as a numeral?",
      "options": [
        "4",
        "5",
        "6"
      ],
      "correct_index": 0,
      "explanation": "The word 'four' is written as the numeral 4.",
      "selected_because": "The lesson asked to write the number word 'four' in numerals.",
      "distractor_misconceptions": {
        "1": "confuses 'four' with 'five'",
        "2": "confuses 'four' with 'six'"
      },
      "option_feedback": {
        "correct": "That's right! The numeral 4 represents the word 'four'.",
        "wrong": {
          "1": "This is the numeral for 'five'. The lesson taught that 'four' is written as 4.",
          "2": "This is the numeral for 'six'. Remember, the word 'four' matches the numeral 4."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Write the number word four in numerals.",
      "teaching_error": null
    },
    {
      "slo_id": "S4",
      "level": "recall",
      "question": "What numeral is shown here?",
      "options": [
        "7",
        "8",
        "9"
      ],
      "correct_index": 0,
      "explanation": "The numeral shown is 7.",
      "selected_because": "Checks reading numbers up to 9 in numerals.",
      "distractor_misconceptions": {
        "1": "misidentifies the numeral as 8",
        "2": "misidentifies the numeral as 9"
      },
      "option_feedback": {
        "correct": "Correct! This is the numeral 7.",
        "wrong": {
          "1": "This is the numeral 8. Look closely at the shape of the numeral to identify 7.",
          "2": "This is the numeral 9. Remember the shape of the numeral 7."
        }
      },
      "figure": {
        "type": "count_objects",
        "picto": "counter",
        "count": 7
      },
      "figure_role": "read_off",
      "source_quote": "read numbers up to 9 in numerals",
      "teaching_error": null
    },
    {
      "slo_id": "S5",
      "level": "recall",
      "question": "What word is for this numeral?",
      "options": [
        "three",
        "two",
        "one"
      ],
      "correct_index": 0,
      "explanation": "The numeral 3 is represented by the word 'three'.",
      "selected_because": "Checks reading numbers up to 9 in words.",
      "distractor_misconceptions": {
        "1": "confuses 'three' with 'two'",
        "2": "confuses 'three' with 'one'"
      },
      "option_feedback": {
        "correct": "You're right! The word for the numeral 3 is 'three'.",
        "wrong": {
          "1": "This is the word 'two'. The numeral shown is 3, which is 'three'.",
          "2": "This is the word 'one'. The numeral 3 is written as 'three'."
        }
      },
      "figure": {
        "type": "word_blank",
        "word": "three",
        "blanks": []
      },
      "figure_role": null,
      "source_quote": "read numbers up to 9 in words",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "apply",
      "question": "If you have 5 apples and get 1 more, how many do you have?",
      "options": [
        "6",
        "5",
        "4"
      ],
      "correct_index": 0,
      "explanation": "Adding 1 to 5 gives a total of 6.",
      "selected_because": "Applies counting to a new scenario.",
      "distractor_misconceptions": {
        "1": "does not add the new item",
        "2": "subtracts instead of adds"
      },
      "option_feedback": {
        "correct": "Excellent! 5 apples plus 1 more makes 6 apples. You counted correctly!",
        "wrong": {
          "1": "You started with 5, but you also got 1 more. Remember to count all of them together. 5 and 1 more makes 6.",
          "2": "It looks like you took one away instead of adding. When you get 1 more, the number goes up. 5 plus 1 is 6."
        }
      },
      "figure": {
        "type": "count_objects",
        "rows": [
          {
            "picto": "apple",
            "count": 5
          },
          {
            "picto": "apple",
            "count": 1,
            "color": "leaf"
          }
        ]
      },
      "figure_role": "model",
      "source_quote": "Count with one touch per object; the last count word is what you write.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which of these shows the numeral for 'zero'?",
      "options": [
        "0",
        "1",
        "2"
      ],
      "correct_index": 0,
      "explanation": "The numeral '0' represents the quantity of nothing, or zero.",
      "selected_because": "The lesson covered numbers from 0 to 9, including zero.",
      "distractor_misconceptions": {
        "1": "confuses 'zero' with 'one'",
        "2": "confuses 'zero' with 'two'"
      },
      "option_feedback": {
        "correct": "That's right! The numeral '0' means there is nothing there, just like an empty box.",
        "wrong": {
          "1": "This is the numeral for 'one'. Remember, 'zero' means no items at all.",
          "2": "This is the numeral for 'two'. The numeral '0' shows when there are no objects to count."
        }
      },
      "figure": {
        "type": "count_frame",
        "count": 0
      },
      "figure_role": "read_off",
      "source_quote": "Count numbers from 0 to 9",
      "teaching_error": null
    }
  ]
}
